from math import factorial

def choose(n, k):
	total = factorial(n) // factorial(k)
	total = total // factorial(n - k)
	return int(total)

def incl(n, k, i):
	total = 1
	for j in range(0, i):
		total = (10 - j) * total * choose(n - j * k, k)
	return total

def excl(n, k, i):
	total = choose(n - 1, k - 1)
	for j in range(1, i):
		total = (10 - j - 1) * total * choose(n - j * k, k)
	return total
T = int(input())
for k in range(T):
	pair = str(input()).split(' ')
	N = int(pair[0])
	K = int(pair[1]) + 1
	total = 10 ** N - 10 ** (N - 1)
	i = 1
	while N >= i * K:
		if i % 2 == 1:
			total = total - incl(N, K, i) + excl(N, K, i)
		else:
			total = total + incl(N, K, i) - excl(N, K, i)
		i = i + 1
	total = total % (10 ** 9 + 7)
	print(total)
